module generics @id("example.generics");

function identity<T> @id("example.generics.identity")(value: T) -> T
ensures { result == value }
{ value }

function contains<T> @id("example.generics.contains")(xs: List<T>, value: T) -> Bool {
  if List::length(xs) == 0 { false } else {
    if List::head(xs) == value { true } else { contains::<T>(List::tail(xs), value) }
  }
}

record Item @id("example.generics.item") { key: I64, name: Text }

function number @id("example.generics.number")(value: I64) -> I64 { identity::<I64>(value) }
function text @id("example.generics.text")(value: Text) -> Text { identity::<Text>(value) }
function item @id("example.generics.echo")(value: Item) -> Item { identity::<Item>(value) }
function has @id("example.generics.has")(xs: List<Item>, value: Item) -> Bool {
  contains::<Item>(xs, value)
}

